
const pool = require('../../db');

const {
  isValidId,
  sendServerError
} = require('../../utils/forms/forms.helpers');

const {
  appendAttachmentToPdf
} = require('../../services/forms/submissionPdf.service');

const {
  PDFDocument
} = require('pdf-lib');

// ==========================================
// GENERATE COMBINED SUBMISSION PDF
// POST /api/forms/submissions/:id/combined-pdf
//
// Receives:
// reviewPdf: PDF generated by the frontend
//
// Returns:
// One PDF containing the review followed by
// all uploaded submission documents.
// ==========================================

exports.generateCombinedSubmissionPdf = async (req, res) => {
  const { id } = req.params;

  if (!isValidId(id)) {
    return res.status(400).json({
      message: 'Invalid submission ID.'
    });
  }

  if (!req.organizationId) {
    return res.status(400).json({
      message: 'An organization must be selected.'
    });
  }

  if (!req.file || !req.file.buffer) {
    return res.status(400).json({
      message: 'The submission review PDF is required.'
    });
  }

  try {
    // --------------------------------------
    // VALIDATE INCOMING REVIEW PDF
    // --------------------------------------

    let combinedPdf;

    try {
      combinedPdf = await PDFDocument.load(req.file.buffer);
    } catch {
      return res.status(400).json({
        message: 'The submitted review document is not a valid PDF.'
      });
    }

    // --------------------------------------
    // RETRIEVE SUBMISSION
    // --------------------------------------

    const submissionResult = await pool.query(
      `SELECT
         fs.id,
         fs.form_snapshot,
         f.name AS form_name
       FROM form_submissions fs
       JOIN forms f
         ON f.id = fs.form_id
        AND f.organization_id = fs.organization_id
       WHERE fs.id = $1
         AND fs.organization_id = $2`,
      [
        id,
        req.organizationId
      ]
    );

    if (submissionResult.rows.length === 0) {
      return res.status(404).json({
        message: 'Submission not found.'
      });
    }

    const submission = submissionResult.rows[0];

    // --------------------------------------
    // IDENTIFY SIGNATURE QUESTIONS
    // --------------------------------------

    const signatureQuestionIds = new Set();

    const sections = submission.form_snapshot?.sections ?? [];

    for (const section of sections) {
      for (const question of section.questions ?? []) {
        if (question.type === 'signature') {
          signatureQuestionIds.add(String(question.id));
        }
      }
    }

    // --------------------------------------
    // RETRIEVE UPLOADED DOCUMENT METADATA
    // --------------------------------------

    const filesResult = await pool.query(
      `SELECT
         id,
         question_id,
         storage_path,
         original_name,
         mime_type,
         uploaded_at
       FROM form_submission_files
       WHERE submission_id = $1
         AND organization_id = $2
       ORDER BY uploaded_at ASC, id ASC`,
      [
        id,
        req.organizationId
      ]
    );

    // Exclude signature images from appended documents.
    const documentFiles = filesResult.rows.filter(
      file => !signatureQuestionIds.has(String(file.question_id))
    );

    // --------------------------------------
    // DETERMINE ORIGINAL QUESTION ORDER
    // --------------------------------------

    const questionOrder = new Map();
    let questionIndex = 0;

    for (const section of sections) {
      for (const question of section.questions ?? []) {
        if (question?.id) {
          questionOrder.set(
            String(question.id),
            questionIndex++
          );
        }
      }
    }

    // Sort by question order, then upload order.
    documentFiles.sort((a, b) => {
      const orderA =
        questionOrder.get(String(a.question_id)) ??
        Number.MAX_SAFE_INTEGER;

      const orderB =
        questionOrder.get(String(b.question_id)) ??
        Number.MAX_SAFE_INTEGER;

      if (orderA !== orderB) {
        return orderA - orderB;
      }

      const dateA = new Date(a.uploaded_at).getTime();
      const dateB = new Date(b.uploaded_at).getTime();

      if (dateA !== dateB) {
        return dateA - dateB;
      }

      return Number(a.id) - Number(b.id);
    });

    // --------------------------------------
    // APPEND ATTACHMENTS
    // --------------------------------------

    // Signature images are intentionally excluded because
    // they are already part of the frontend review PDF.
    for (const file of documentFiles) {
      await appendAttachmentToPdf(combinedPdf, file);
    }

    // --------------------------------------
    // GENERATE FINAL PDF
    // --------------------------------------

    const pdfBytes = await combinedPdf.save();

    const filename = `submission-${id}.pdf`;

    res.setHeader('Content-Type', 'application/pdf');

    res.setHeader(
      'Content-Disposition',
      `attachment; filename="${filename}"`
    );

    res.setHeader(
      'Content-Length',
      pdfBytes.length
    );

    return res.status(200).send(Buffer.from(pdfBytes));

  } catch (error) {
    return sendServerError(
      res,
      error,
      'Error generating combined submission PDF:'
    );
  }
};